import sympy

def calculate_wick_contraction(mode="diagonal"):
    Lambda, t = sympy.symbols('Lambda t', real=True)
    V_LL, V_LR, V_RL, V_RR = sympy.symbols('V_LL V_LR V_RL V_RR', commutative=True)

    V = sympy.Matrix([
        [V_LL, V_LR],
        [V_RL, V_RR]
    ])

    prefactor = Lambda * t**2

    if mode == "diagonal":
        result = sympy.Matrix([
            [prefactor * V_LL**2, prefactor * V_LR**2],
            [prefactor * V_RL**2, prefactor * V_RR**2]
        ])
    elif mode == "full_sum":
        row_sums = [sum(V[i, k] for k in range(2)) for i in range(2)]
        col_sums = [sum(V[m, j] for m in range(2)) for j in range(2)]

        result = sympy.Matrix([
            [prefactor * row_sums[i] * col_sums[j] for j in range(2)]
            for i in range(2)
        ])
    else:
        raise ValueError(f"Unknown mode: {mode}")

    return [[str(result[i, j]) for j in range(2)] for i in range(2)]
